SELECT COUNT(*)
FROM TB_CHAT_MSG
WHERE ROOM_NO   = #{roomNo}
  AND SENDER_NO != #{memberNo}
  AND READ_YN    = 'N'

mapper.update:
UPDATE TB_CHAT_MSG
   SET READ_YN = 'Y'
 WHERE ROOM_NO   = #{roomNo}
   AND SENDER_NO != #{memberNo}
   AND READ_YN    = 'N'
